/** Board-local line segments. Never connect across a row wrap or draw an
 * internal border between two cells in the same basket region. */
export interface GapEdge {from:[number,number];to:[number,number];}
export function gapRegionEdges(cells:number[],columns:number,rows:number):GapEdge[]{
 const region=new Set(cells.filter(c=>Number.isInteger(c)&&c>=0&&c<columns*rows)),edges:GapEdge[]=[];
 for(const c of region){const x=c%columns,y=Math.floor(c/columns);
  if(y===0||!region.has(c-columns))edges.push({from:[x,y],to:[x+1,y]});
  if(y===rows-1||!region.has(c+columns))edges.push({from:[x,y+1],to:[x+1,y+1]});
  if(x===0||!region.has(c-1))edges.push({from:[x,y],to:[x,y+1]});
  if(x===columns-1||!region.has(c+1))edges.push({from:[x+1,y],to:[x+1,y+1]});
 }return edges;
}
export function gapPathEdges(cells:number[],columns:number):GapEdge[]{
 const edges:GapEdge[]=[];for(let i=1;i<cells.length;i++){const a=cells[i-1],b=cells[i],ax=a%columns,ay=Math.floor(a/columns),bx=b%columns,by=Math.floor(b/columns);if(Math.abs(ax-bx)+Math.abs(ay-by)!==1)throw Error('Disconnected gap path');edges.push({from:[ax+.5,ay+.5],to:[bx+.5,by+.5]});}return edges;
}
