import {isLocalMode} from './LocalMode';
import {QUEST_CATALOG_ID} from './QuestCatalog';
import type {QuestEvidence,QuestSnapshot,QuestState} from './QuestPolicy';
export interface MissionEvent {id:string;slot:string;bet:number;payout:number;completedAt:number;quest:QuestEvidence;}
export interface QuestReply {snapshot:QuestSnapshot;state?:QuestState;save?:unknown;revision?:number;creditedCoins?:number;alreadyClaimed?:boolean;}
const QUEST_URL='https://asia-northeast3-in-my-pocket-slots.cloudfunctions.net/quests';
const unavailable=()=>Object.assign(Error('QUEST_UNAVAILABLE'),{code:'QUEST_UNAVAILABLE'});
/** JSB exposes XMLHttpRequest on devices where fetch is absent. */
export async function postGameRequest(token:string,url:string,payload:string):Promise<{status:number;text:string}>{
 if(typeof fetch!=='function')return new Promise((resolve,reject)=>{
  const xhr=new XMLHttpRequest();xhr.open('POST',url,true);xhr.timeout=20000;
  xhr.setRequestHeader('Content-Type','application/json');xhr.setRequestHeader('Authorization','Bearer '+token);
  xhr.onload=()=>resolve({status:xhr.status,text:xhr.responseText});xhr.onerror=()=>reject(unavailable());xhr.ontimeout=()=>reject(unavailable());xhr.send(payload);
 });
 let timer:ReturnType<typeof setTimeout>|undefined;
 const controller=typeof AbortController==='function'?new AbortController():undefined;
 try{return await Promise.race([
  fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:payload,...(controller?{signal:controller.signal}:{})}).then(async response=>({status:response.status,text:await response.text()})),
  new Promise<never>((_,reject)=>{timer=setTimeout(()=>{controller?.abort();reject(unavailable());},20000);})
 ]);}finally{if(timer)clearTimeout(timer);}
}
export async function questRequest(token:string,action:'status'|'claim'|'event'|'complete',details?:{expectedRevision:number;requestId:string}|{event:MissionEvent}|{dayId:string;ids:string[]}):Promise<QuestReply>{
 if(isLocalMode())throw Object.assign(Error('QUEST_ONLINE_ONLY'),{code:'QUEST_ONLINE_ONLY'});
 const response=await postGameRequest(token,QUEST_URL,JSON.stringify({action,catalogId:QUEST_CATALOG_ID,...details}));
 let body:any;try{body=JSON.parse(response.text);}catch{body={};}
 if(response.status<200||response.status>=300)throw Object.assign(Error(body.error||'QUEST_UNAVAILABLE'),{code:body.error||'QUEST_UNAVAILABLE',httpStatus:response.status});
 if(!body.snapshot||!Array.isArray(body.snapshot.daily)||body.snapshot.daily.length!==20||!Array.isArray(body.snapshot.lifetime)||!Array.isArray(body.snapshot.milestones)||!Number.isSafeInteger(body.snapshot.pendingCoins)||body.snapshot.pendingCoins<0)throw unavailable();
 return body as QuestReply;
}
