  for(let left=11;left>=0;left--){const b=this.draw(bet,rng),prior=Array.from(held.keys()),v=values(b);held.forEach((n,c)=>{b[c]=this.id('wild');v[c]=n;});const landed=cells(b,this.id('wild')).filter(c=>!held.has(c)),frames=[this.frame(b,'reels','고정 개집 유지 · 새 개집 착지',[],{held:prior,values:v})];if(landed.length)frames.push(this.frame(b,'trigger','새 WILD ×2 / ×3 강조',landed,{held:prior,values:v}));landed.forEach(c=>held.set(c,v[c]));if(landed.length)frames.push(this.frame(b,'effect','고정 표시 → 다음 회전까지 유지',landed,{held:Array.from(held.keys()),values:v}));frames.push(this.hit(b,bet,'개집 배수 적용',this.geometry,{values:v,wildMode:'product'}));rounds.push(this.round(bet,frames,{heldAtStart:prior.map(cell=>({cell,symbol:this.id('wild'),value:v[cell]})),freeSpinsRemaining:left}));}
