   const col=cell%5,options=this.config.symbols.filter(s=>s.weight>0&&(!free||s.id!==this.id('scatter'))&&(!(col===0||col===4)||s.id!==this.id('wild'))&&!(s.id===this.id('scatter')&&out.some((id,c)=>c%5===col&&id===s.id)));
