  if(heights.some((h,c)=>h!==before[c]))fs.push(this.frame(Array(5*Math.max(...before)).fill(''),'trigger','릴별 높이 공개',[],{panel},{columns:5,rows:Math.max(...before)}),this.frame(Array(g.rows*5).fill(''),'expand','커튼 열림 · 활성 위치 확장',[],{panel},g));
  fs.push(this.frame(visible,'reels',free?'확장 무료 회전':'정글 릴 정지',[],{panel},g),{...this.hit(raw,bet,ways+' WAYS · 활성 위치 당첨',g,{height:heights}),board:visible,panel});
  const prizes=cells(visible,this.id('prize'));if(prizes.length>=3){const multiple=[1,3,10,25,50,100,500][Math.min(9,prizes.length)-3];fs.push(this.frame(visible,'trigger','사원 코인 '+prizes.length+'개 · 별도 상금',prizes,{panel},g),{...this.prize(visible,bet,multiple,prizes,'사원 코인 상금',g),panel});}
