   for(let left=count-1;left>=0;left--){const next=previous.map(h=>Math.min(6,h+(rng()<.35?1+ri(rng,3):0))),r=this.heightRound(bet,rng,next,previous,true);r.freeSpinsRemaining=left;r.roundLabel='FREE SPINS · '+(count-left)+'/'+count;rounds.push(r);previous=next;}
