import {FeatureGame,Random,choose,sampleCells} from './FeatureKit';
import {featureDefinitions} from './FeatureDefinitions';
import {SpinResult} from './SlotMain';
/** Mystery conversion + golden collector rounds, with progressive low-symbol conversions. */
export class CookieLabSlot extends FeatureGame {
 constructor(){super(featureDefinitions['cookie-lab']);}
 spin(bet:number,rng:Random=Math.random):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  let converted=0,meter=0,extra=0,goldenMultiplier=1;
  const roll=(free=false):SpinResult=>{
   const board=this.rollBoard(rng),mystery:number[]=[],values=Array(30).fill(0);
   for(let i=0;i<30;i++)if(rng()<.035||(free&&this.config.symbols.slice(4,4+converted).some(s=>s.id===board[i])))mystery.push(i);
   for(const i of mystery)board[i]=this.config.id+'-8';
   if(!free&&rng()<.018)this.scatter(board,rng,3);if(free&&rng()<.28)this.scatter(board,rng,1);
   const opening=[...board],gold=rng()<.22,reveal=rng()<.10?this.wildSymbol:choose(this.config.symbols.slice(0,8),rng).id;
   for(const i of mystery)if(board[i]!==this.bonusSymbol)board[i]=gold?this.config.id+'-9':reveal;
   const r=this.evaluate(board,bet,Array(30).fill(1));r.openingBoard=opening;r.expandedCells=mystery.filter(i=>opening[i]!==this.bonusSymbol);r.symbolValues=values;
   if(gold){const positions=mystery.filter(i=>board[i]===this.config.id+'-9'),collectors:number[]=[],cash:number[]=[];
    for(const i of positions){const kind=rng();if(kind<.75){values[i]=choose([1,1,2,3,5,10,20,50,100,500,5000],rng);cash.push(i);}else if(kind<.86){collectors.push(i);board[i]=this.config.id+'-11';}else if(kind<.94){const m=choose([2,3,5,10],rng);for(const c of cash)values[c]*=m;}else if(free)extra+=choose([1,2,3],rng);}
    let total=cash.reduce((n,i)=>n+values[i],0);for(const i of collectors){values[i]=total;total+=values[i];}
    this.addCash(r,[...cash,...collectors],total*goldenMultiplier,'황금 오븐 · 수집 ×'+goldenMultiplier);r.collectorCells=collectors;r.moneyCells=cash;
   }
   if(free){meter+=this.count(opening,this.bonusSymbol);while(meter>=4&&converted<4){meter-=4;extra+=[4,3,3,2][converted];converted++;goldenMultiplier++;}}
   r.featureText='오븐 전환 '+converted+'/4 · SCATTER '+meter+'/4 · 황금 ×'+goldenMultiplier;return r;
  };
  const base=roll(),rounds=[base];if(this.count(base.board,this.bonusSymbol)<3)return this.finish(rounds,'');
  converted=choose([0,0,2,4],rng);goldenMultiplier=converted+1;const initial=converted===4?choose([8,9,10],rng):choose([7,8,9],rng);let left=initial;
  for(let i=0;left>0&&i<100;i++){left--;extra=0;const r=roll(true);left+=extra;r.roundLabel='제과 프리스핀 · 남은 '+left+'회'+(extra?' · +'+extra:'');rounds.push(r);}return this.finish(rounds,'제과 프리스핀',initial);
 }
}
/** Four-symbol stacks nudge and reveal; the bonus tracks its own moving stacks. */
export class DesertExpressSlot extends FeatureGame {
 constructor(){super(featureDefinitions['desert-express']);}
 spin(bet:number,rng:Random=Math.random):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');let multiplier=1;const offsets=[0,0];
  const roll=(free=false):SpinResult=>{
   const board=this.rollBoard(rng),mystery:number[]=[],values=Array(20).fill(0);let nudges=0;
   if(free){[1,3].forEach((col,k)=>{for(let row=0;row<4;row++)if(row>=offsets[k]&&row<offsets[k]+4)mystery.push(row*5+col);offsets[k]++;nudges++;});multiplier+=nudges;}
   else if(rng()<.12){const col=Math.floor(rng()*5);for(let row=0;row<4;row++)mystery.push(row*5+col);}
   for(const i of mystery)board[i]=this.config.id+'-8';if(!free&&rng()<.018)this.scatter(board,rng,choose([3,3,3,4,5],rng));
   const opening=[...board],gold=rng()<.15,reveal=choose(this.config.symbols.slice(0,8),rng).id,cash:number[]=[];
   for(const i of mystery)if(board[i]!==this.bonusSymbol){if(gold){board[i]=this.config.id+'-9';values[i]=choose([1,2,3,5,10,20,50,100,500,2500],rng);cash.push(i);}else board[i]=rng()<.06?this.wildSymbol:reveal;}
   const r=this.evaluate(board,bet,Array(20).fill(1));for(const win of r.wins){win.amount*=free?multiplier:1;win.multiplier=free?multiplier:1;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);
   if(cash.length)this.addCash(r,cash,cash.reduce((n,i)=>n+values[i],0)*(free?multiplier:1),'황금 화물 공개');r.symbolValues=values;r.openingBoard=opening;r.expandedCells=mystery.filter(i=>opening[i]!==this.bonusSymbol);r.featureText=free?'이동 스택 '+Math.max(0,4-offsets[0])+'칸 · 전체 ×'+multiplier:'미스터리 화물 → 스택 공개';return r;
  };
  const base=roll(),rounds=[base],count=this.count(base.board,this.bonusSymbol);if(count<3)return this.finish(rounds,'');
  offsets.fill(-(count-3));const initial=4+(count-3);for(let i=0;i<initial;i++){const r=roll(true);r.roundLabel='사막 프리스핀 '+(i+1)+'/'+initial;rounds.push(r);}return this.finish(rounds,'사막 프리스핀',initial);
 }
}
