import {ExpansionSlot,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
/** Local 720-way adaptation: each reel must contain an eye; multiple eyes multiply free games. */
export class TundraTwoWaySlot extends ExpansionSlot {
 readonly heights=[3,4,5,4,3];
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);this.config.symbols.push({id:this.id('white-eye'),name:'white tiger eyes',color:'#dfeeff',weight:0,payout:0},{id:this.id('ice-star'),name:'ice star scatter',color:'#a6d7ff',weight:2,payout:0});this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=6;}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-eyes';}
 get bonusTriggerCount(){return 5;}
 private pool(free:boolean){return this.config.symbols.map(s=>({...s,weight:s.id===this.id('scatter')?(free?0:6):s.id===this.id('white-eye')?(free?5:0):s.weight})).filter(s=>s.weight>0);}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private active(c:number){return Math.floor(c/5)<this.heights[c%5];}
 private mask(board:string[]){return board.map((s,c)=>this.active(c)?s:'');}
 private stacks(board:string[],rng:()=>number){for(let col=0;col<5;col++){const wilds=cells(board,this.id('wild')).filter(c=>c%5===col&&this.active(c));if(!wilds.length)continue;const anchor=Math.floor(wilds[0]/5),size=2+randomIndex(rng,2),starts=Array.from({length:this.heights[col]-size+1},(_,i)=>i).filter(start=>start<=anchor&&anchor<start+size),start=starts[randomIndex(rng,starts.length)];for(let r=start;r<start+size;r++){const c=r*5+col;if(board[c]===this.id('wild')||this.config.symbols.slice(0,8).some(s=>s.id===board[c]))board[c]=this.id('wild');}}return board;}
 private grid(bet:number,rng:()=>number,free:boolean,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid bet');const pool=this.pool(free),gate=this.id(free?'white-eye':'scatter'),plain=pool.filter(s=>s.id!==gate),p=pool.find(s=>s.id===gate)!.weight/pool.reduce((n,s)=>n+s.weight,0),board=Array<string>(25).fill(this.id(7));
  for(let col=0;col<5;col++){let seen:boolean=false;for(let row=0;row<this.heights[col];row++){const chance:number=conditional&&!seen?p/(1-(1-p)**(this.heights[col]-row)):p;const id:string=rng()<chance?gate:this.weighted(rng,plain);board[row*5+col]=id;seen ||= id===gate;}}
  return this.stacks(board,rng);
 }
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.grid(bet,rng,false);}
 private gates(board:string[],free=false){return cells(board,this.id(free?'white-eye':'scatter')).filter(c=>this.active(c));}
 private freeCount(board:string[],free=false){const gates=this.gates(board,free),ways=this.heights.reduce((n,_,col)=>n*gates.filter(c=>c%5===col).length,1);return Math.min(96,8*ways);}
 private tundraRound(board:string[],bet:number,free:boolean){const wilds=cells(board,this.id('wild')).filter(c=>this.active(c)),frames=[this.frame(board,'reels',free?'흰 호랑이 눈 · 노을 무료 회전':'얼음 능선 · 720 양방향 WAYS')];if(wilds.length)frames.push(this.frame(board,'trigger','세로 WILD 스택 · 일반 심볼 대체',wilds));frames.push(this.hit(board,bet,'양쪽 끝에서 연결 · 5릴 완성은 한 번 지급',this.geometry,{reverse:true,height:this.heights}));const stars=cells(board,this.id('ice-star')).filter(c=>this.active(c));if(stars.length>=3){const mult=stars.length>=5?50:stars.length===4?10:2,f=this.prize(board,bet,mult,stars,'얼음 별 SCATTER · 베팅 ×'+mult);f.wins.forEach(w=>{w.symbol=this.id('ice-star');w.amount=bet*mult;w.multiplier=mult;});frames.push(f);}frames.forEach(f=>f.board=this.mask(f.board));return this.round(bet,frames);}
 play(board:string[],bet:number,rng:()=>number){const base=this.tundraRound(board,bet,false),count=this.freeCount(board);if(!count)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(this.mask(board),'trigger','다섯 릴 눈 조합 · 무료 '+count+'회',this.gates(board)));const rounds=[base];let left=count,total=count;while(left>0){left--;const b=this.grid(bet,rng,true),round=this.tundraRound(b,bet,true),added=Math.min(this.freeCount(b,true),240-total);if(added){left+=added;total+=added;round.freeSpinsAdded=added;round.expansionFeature!.frames.push(this.frame(this.mask(b),'trigger','흰 눈 조합 · 무료 +'+added+'회',this.gates(b,true)));}round.freeSpinsRemaining=left;rounds.push(round);}return this.finish(rounds,{freeSpinsAwarded:count,featureOnly:false});}
 prepareBonusPurchase(bet:number,rng:()=>number){return this.purchaseFromResult(this.play(this.grid(bet,rng,false,true),bet,rng));}
}
