/** Coin entry is 100× base bet. Ticket currency is retired. */
export const BONUS_COST_MULTIPLIER=100;
export function bonusTicketCost(baseBet:number):number {
 if(!Number.isSafeInteger(baseBet)||baseBet<=0||!Number.isSafeInteger(baseBet*BONUS_COST_MULTIPLIER))throw Error('Invalid bonus bet');
 return 0;
}
