import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
/** Observed four-array Coin Grab and 9/6/3 free choices. Weights and tier awards are local. */
export class SumoRingSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);for(const name of ['free','portrait','unlock'])this.config.symbols.push({id:this.id(name),name,color:'#f2cb86',weight:0,payout:0});this.config.description='5×3 · 50라인 · 왼쪽부터 연결\n붉은 코인 6개: 금고 1개로 시작. 황금 코인 6개: 같은 시작 코인을 네 금고에 복사합니다.\n열린 금고 코인 8/16/36개: 두 번째/세 번째/네 번째 금고를 해금합니다.\n리스핀 3회. 열린 금고에 새 코인이 오면 3회 복구하며 잠긴 금고의 코인도 고정됩니다.\n해금된 금고만 마지막에 한 번 지급. 각 금고 15칸 완성은 별도 고정 상금입니다.\n가운데 3릴 BONUS: 무료 9/6/3회 선택, 코인 발동 문턱은 6/5/4개. 무료 WILD는 해당 릴 전체로 확장됩니다.\n재발동은 선택 횟수 추가, 최대90회. 출현 확률·티어·재발동 횟수는 로컬 규칙이며 공유 잭팟은 없습니다.';}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-sumo';}
 get bonusSymbol(){return this.id('free');}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const out:string[]=[];for(let c=0;c<15;c++){const pool=this.config.symbols.filter(s=>s.weight>0&&s.id!==this.id('scatter'));pool.push({id:this.id('scatter'),name:'red',color:'',payout:0,weight:12},{id:this.id('coin'),name:'gold',color:'',payout:0,weight:3});if(c%5>0&&c%5<4&&!out.some((s,i)=>i%5===c%5&&s===this.id('free')))pool.push({id:this.id('free'),name:'free',color:'',payout:0,weight:7});out.push(this.weighted(rng,pool));}return out;}
 private freeGate(b:string[]){return [1,2,3].every(col=>b.some((id,c)=>c%5===col&&id===this.id('free')));}
 private hold(board:string[],bet:number,rng:()=>number,superMode:boolean):SpinResult[]{
  const boards=Array.from({length:4},()=>new Map<number,number>()),global=(p:number,c:number)=>Math.floor(p/2)*30+Math.floor(c/5)*10+p%2*5+c%5,rounds:SpinResult[]=[],snaps:ExpansionFrame[]=[];let unlocked=superMode?4:1,left=3;
  const values=()=>[1,2,3,5,10,20][ri(rng,6)],symbol=this.id(superMode?'coin':'scatter');for(const c of cells(board,symbol)){const v=values();for(let p=0;p<(superMode?4:1);p++)boards[p].set(c,v);}
  const count=()=>boards.slice(0,unlocked).reduce((n,b)=>n+b.size,0),frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[])=>{const b=Array(60).fill(''),held:number[]=[];for(let p=0;p<4;p++)for(const c of boards[p].keys()){b[global(p,c)]=symbol;held.push(global(p,c));}const f=this.frame(b,action,caption,focus,{held,remaining:left,sumoVault:{unlocked,superMode,filled:boards.map(b=>b.size),collected:count()},panel:{label:'SUMO HOLD',values:[unlocked,count()],columns:2}},{columns:10,rows:6});snaps.push(f);return f;};
  rounds.push(this.round(bet,[frame('reveal',superMode?'황금 코인 · 같은 시작판을 네 금고에 복사':'붉은 코인 · 첫 금고 해금 · 리스핀 3회')]));
  const unlock=(fs:ExpansionFrame[])=>{while(unlocked<4&&count()>=[8,16,36][unlocked-1]){const p=unlocked;fs.push(frame('trigger','열린 금고 코인 '+[8,16,36][p-1]+'개 · 다음 금고 해금',[global(p,7)]));unlocked++;fs.push(frame('effect','금고 '+unlocked+' 해금 · 저장된 코인도 합산',[global(p,7)]));}};
  const initial:ExpansionFrame[]=[];unlock(initial);if(initial.length)rounds.push(this.round(bet,initial));
  while(left>0&&boards.some(b=>b.size<15)){left--;const fs=[frame('reels','고정 코인 유지 · 네 금고 빈칸 회전')],active=unlocked,landed:number[]=[];let reset=false;for(let p=0;p<4;p++)for(let c=0;c<15;c++)if(!boards[p].has(c)&&rng()<.038){boards[p].set(c,values());landed.push(global(p,c));if(p<active)reset=true;}if(reset)left=3;if(landed.length)fs.push(frame('effect',reset?'열린 금고 새 코인 · 3회 복구':'잠긴 금고 코인 고정 · 횟수는 복구하지 않음',landed));unlock(fs);fs.push(frame('state','열린 금고만 최종 지급 · 남은 '+left+'회'));rounds.push(this.round(bet,fs));}
  left=0;const awards=new Map<number,Win>();for(let p=0;p<unlocked;p++)for(const [c,v]of boards[p]){const cell=global(p,c);awards.set(cell,{line:-1,symbol,cells:[cell],amount:Math.round(bet*v*this.payoutFactor),multiplier:v*this.payoutFactor});}
  const first=Array.from(awards.values())[0],firstRaw=first.amount;const paid=frame('collect','해금 금고 → 코인 숫자만 수집 · 한 번 지급',Array.from(awards.keys()));paid.wins=Array.from(awards.values());rounds.push(this.round(bet,[paid]));for(let p=0;p<unlocked;p++)if(boards[p].size===15){const f=frame('win','금고 '+(p+1)+' 15칸 완성 · 고정 GRAND',[global(p,7)]);f.wins=[{line:-1,symbol:this.id('portrait'),cells:[global(p,7)],amount:Math.round(bet*100*this.payoutFactor),multiplier:100*this.payoutFactor}];rounds.push(this.round(bet,[f]));}
  // Unopened potential coins share a scalable reference, but never enter the paid wins.
  for(const f of snaps)f.coinAwards=f.board.flatMap((id,cell)=>{if(!id)return[];const p=Math.floor(cell/30)*2+Math.floor(cell%10/5),c=Math.floor(cell%30/10)*5+cell%5;return[{cell,win:awards.get(cell)||first,...(awards.has(cell)?{}:{fraction:Math.round(bet*boards[p].get(c)!*this.payoutFactor)/Math.max(1,firstRaw)})}];});return rounds;
 }
 private freeRounds(base:SpinResult,bet:number,rng:()=>number,index:number){const rounds=[base],initial=[9,6,3][index],threshold=[6,5,4][index];let left=initial,awarded=initial;while(left>0){left--;const b=this.draw(bet,rng),wilds=cells(b,this.id('wild')),expanded=[...b];for(const c of wilds)for(let row=0;row<3;row++)expanded[row*5+c%5]=this.id('wild');const fs=[this.frame(b,'reels','스모 무료 회전')];if(wilds.length)fs.push(this.frame(expanded,'effect','스모 WILD · 해당 릴 전체 확장',expanded.flatMap((s,c)=>s!==b[c]?[c]:[])));fs.push(this.hit(expanded,bet,'확장 WILD 라인 당첨',{columns:5,rows:3}));const added=this.freeGate(b)?Math.min(initial,90-awarded):0;if(added){left+=added;awarded+=added;fs.splice(1,0,this.frame(b,'trigger','BONUS 재발동 · 무료 +'+added,cells(b,this.id('free'))));}for(const f of fs)f.panel={label:'SUMO FREE',values:[left,threshold],columns:2};rounds.push(this.round(bet,fs,{freeSpinsRemaining:left,freeSpinsAdded:added||undefined}));const gold=cells(b,this.id('coin')),red=cells(b,this.id('scatter')),superMode=gold.length>=threshold;if(superMode||red.length>=threshold){rounds.push(this.round(bet,[this.frame(b,'trigger','무료 중 코인 '+threshold+'개 · 멀티 금고 진입',superMode?gold:red)]),...this.hold(b,bet,rng,superMode));}}
 return this.finish(rounds,{freeSpinsAwarded:initial,featureOnly:false});}
 private branches(base:SpinResult,bet:number,rng:()=>number){return this.choices('무료 회전과 코인 문턱 선택',['9회 · 코인 6개','6회 · 코인 5개','3회 · 코인 4개'],[0,1,2].map(i=>this.freeRounds(JSON.parse(JSON.stringify(base)),bet,rng,i)));}
 play(b:string[],bet:number,rng:()=>number){this.validate(b,bet,{columns:5,rows:3});const base=this.ordinary(b,bet,undefined,{columns:5,rows:3}),gold=cells(b,this.id('coin')),red=cells(b,this.id('scatter')),superMode=gold.length>=6;if(superMode||red.length>=6){base.expansionFeature!.frames.push(this.frame(b,'trigger','코인 6개 이상 · 멀티 금고',superMode?gold:red));return this.finish([base,...this.hold(b,bet,rng,superMode)],{featureOnly:true});}if(this.freeGate(b)){base.expansionFeature!.frames.push(this.frame(b,'trigger','가운데 3릴 BONUS · 무료 선택',cells(b,this.id('free'))));return this.branches(base,bet,rng);}return this.finish([base]);}
 prepareBonusPurchase(bet:number,rng:()=>number){for(let n=0;n<50000;n++){const b=this.draw(bet,rng);if(this.freeGate(b)&&cells(b,this.id('coin')).length<6&&cells(b,this.id('scatter')).length<6)return this.purchaseFromResult(this.branches(this.round(bet,[this.frame(b,'trigger','독립 무료 스모 보너스',cells(b,this.id('free')))]),bet,rng));}throw Error('Sumo free bonus unavailable');}
}
