import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
export const CLOCKWORK_LINES=[[5,6,7,8,9],[0,1,2,3,4],[10,11,12,13,14],[0,6,12,8,4],[10,6,2,8,14]];
/** Public paytable facts; original art and independent prototype symbol sampling. */
export class ClockworkSlot extends SlotMain {
 readonly hasBonus=true;get bonusSymbol(){return 'parcel';}readonly maxWin=1040;
 readonly columns=5;readonly rows=3;readonly paylines=CLOCKWORK_LINES;
 readonly pays:Record<string,number[]>={robot:[0,0,100,1000,5000],clock:[0,0,50,200,1000],key:[0,0,50,200,1000],bell:[0,0,20,50,200],gear:[0,0,20,50,200],gem:[0,0,20,40,200],ticket:[0,5,20,40,200]};
 readonly config:SlotConfig={id:'clockwork',title:'태엽 극장',subtitle:'CLOCKWORK THEATRE',tag:'5 REELS',color:'#493348',accent:'#edb76e',description:'황동 태엽과 작은 로봇의 극장.\n5개 릴 · 5개 라인 · 선물상자 스캐터',symbols:[
  {id:'robot',name:'로봇',color:'#93d3c4',weight:5,payout:5000},{id:'clock',name:'시계',color:'#edb76e',weight:8,payout:1000},{id:'key',name:'열쇠',color:'#edb76e',weight:10,payout:1000},{id:'bell',name:'종',color:'#edb76e',weight:15,payout:200},{id:'gear',name:'톱니',color:'#e49378',weight:17,payout:200},{id:'gem',name:'보석',color:'#b0a0d1',weight:20,payout:200},{id:'ticket',name:'리본',color:'#f0a3bb',weight:23,payout:200},{id:'parcel',name:'선물상자',color:'#b2d995',weight:4.66845703125,payout:250}]};
 spin(bet:number,rng:()=>number=Math.random):SpinResult{return this.freeSpinSequence(this.spinRound(bet,rng),()=>this.spinRound(bet,rng),round=>round.board.filter(id=>id==='parcel').length>=3?8:0);}
 private spinRound(bet:number,rng:()=>number):SpinResult{if(!this.bets.includes(bet))throw Error('Invalid bet');const board=Array<string>(15);for(let col=0;col<5;col++){let scatter=false;for(let row=0;row<3;row++){let id=this.pick(rng);if(id==='parcel'&&scatter)id='ticket';if(id==='parcel')scatter=true;board[row*5+col]=id;}}return this.evaluate(board,bet);}
 evaluate(board:string[],bet:number):SpinResult{if(board.length!==15||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid board');const wins:Win[]=[];
  CLOCKWORK_LINES.forEach((line,index)=>{const id=board[line[0]];if(!this.pays[id])return;let count=1;while(count<5&&board[line[count]]===id)count++;const amount=this.pays[id][count-1]*bet/5;if(amount)wins.push({line:index,symbol:id,cells:line.slice(0,count),amount});});
  const scatters=board.map((id,i)=>id==='parcel'?i:-1).filter(i=>i>=0);if(scatters.length>=3)wins.push({line:-1,symbol:'parcel',cells:scatters,amount:bet*([10,50,250][Math.min(5,scatters.length)-3])});
  let remaining=bet*1040;for(const win of wins){win.amount=Math.min(remaining,win.amount);remaining-=win.amount;}return {board:[...board],bet,wins:wins.filter(w=>w.amount>0),payout:bet*1040-remaining};
 }
 demoSpin(bet:number){return this.evaluate(['parcel','clock','parcel','key','parcel','ticket','ticket','ticket','gear','bell','bell','gem','key','clock','gear'],bet);}
}
