import type {SymbolSpec} from './SlotMain';

/** Draw from the legal weighted pool, without substituting a fixed symbol. */
export function drawReelBoard(columns:number,rows:number,symbols:Pick<SymbolSpec,'id'|'weight'>[],scatter:string|undefined,rng:()=>number):string[]{
 const board=Array<string>(columns*rows);
 const all=symbols.filter(s=>s.weight>0),ordinary=all.filter(s=>s.id!==scatter);
 if(!all.length||!ordinary.length)throw Error('Reel requires weighted non-scatter symbols');
 for(let col=0;col<columns;col++){
  let used=false;
  for(let row=0;row<rows;row++){
   const pool:Pick<SymbolSpec,'id'|'weight'>[]=used?ordinary:all;
   let roll=rng()*pool.reduce((sum,s)=>sum+s.weight,0),id:string=pool[pool.length-1].id;
   for(const symbol of pool){roll-=symbol.weight;if(roll<0){id=symbol.id;break;}}
   board[row*columns+col]=id;used ||= id===scatter;
  }
 }
 return board;
}

/** Passing filler must not invent scatter anticipation between real boards. */
export function reelFillerSymbols(symbols:string[],scatter:string|undefined,restrict:boolean){
 const pool=restrict?symbols.filter(id=>id!==scatter&&!/(?:^|[-_])(scatter|bonus)(?:$|[-_])/i.test(id)):symbols;
 if(!pool.length)throw Error('Reel has no legal passing symbols');
 return pool;
}
