import {SpinResult,SlotMain} from './SlotMain';
import {scalePayout} from './PayoutPolicy';
import {socialSlotCatalog} from './SocialSlotCatalog';
// Base-only paytable changes provide support for 10x+ regular wins; free-spin payouts retain their own scale.
export const basePayoutBoost:Record<string,number>={animal:4,'windup-workshop':10,'space-scrap':3,'mushroom-rush':2,'pizza-courier':8,'robot-duel':8,'coral-post':3,'neon-greenhouse':5,'take-five-jackpot':10,'hello-vegas-night':5,'double-down-street':5,'golden-bingo-room':5};
const socialIds=new Set(socialSlotCatalog.map(slot=>slot.id));
// Legacy blanket boosts were calibrated for another engine and multiply the
// rebuilt social games' actual symbol awards again. Never apply them here.
export function basePayoutFactor(slot:SlotMain){return socialIds.has(slot.config.id)?1:(basePayoutBoost[slot.config.id]||1);}
export function boostBase(slot:SlotMain,result:SpinResult,rng:()=>number){const factor=basePayoutFactor(slot);if(factor===1)return result;const base=result.rounds?.[0]||result;scalePayout(base,factor,rng);if(result.rounds)result.payout=result.rounds.reduce((n,r)=>n+r.payout,0);return result;}
