import type {Cascade,SpinResult} from './SlotMain';
import type {VikingDestructionResult} from './VikingRagnarok';
import {vikingOrdinaryCascade} from './VikingCascade';
import {vikingOrdinaryResult,vikingSymbol} from './VikingResult';
export interface VikingEffectPlayback {
 kind:VikingDestructionResult['kind'];
 waves:number[][];
 removed:number[];
 changed:{cell:number;symbol:string}[];
 transformed:string[];
}
/** Effect demonstration/segment adapter. Full round composition must preserve
 * preceding base awards and resolve any further Ragnarok boundary separately.
 * Destruction itself is never a paid win or a charge increment.
 */
export function vikingDestructionStage(effect:VikingDestructionResult):Cascade{
 const waves=effect.kind==='fenrir'?effect.slashes.map(line=>[...line.cells])
  :effect.kind==='jormungandr'?effect.path.map(cell=>[cell])
  :effect.kind==='surtr'?effect.groups.map(group=>[...group.burned])
  :[[...effect.removed],effect.changed.map(change=>change.cell)];
 const moved=new Map(effect.falls.map(f=>[f.to,f.from]));
 const spawned=new Map(effect.spawned.map(s=>[s.cell,s.symbol]));
 const incoming=Array.from({length:7},(_,col)=>effect.spawned.filter(s=>s.cell%7===col).length);
 const drops=effect.after.map((symbol,to)=>{
  const col=to%7,row=Math.floor(to/7),fresh=spawned.has(to),from=fresh?(row-incoming[col])*7+col:moved.get(to)??to;
  if(fresh?(from>=0||spawned.get(to)!==symbol):(effect.removed.includes(from)||effect.transformed[from]!==symbol))throw Error('Invalid Viking effect fall mapping');
  return {from,to,symbol:vikingSymbol(symbol)};
 });
 const stage:Cascade={board:effect.before.map(vikingSymbol),wins:[],payout:0,multiplier:1,cellMultipliers:Array(49).fill(0),nextMultipliers:Array(49).fill(0),drops,
  vikingEffect:{kind:effect.kind,waves,removed:[...effect.removed],changed:effect.changed.map(c=>({cell:c.cell,symbol:vikingSymbol(c.to)})),transformed:effect.transformed.map(vikingSymbol)}};
 return stage;
}

export function vikingEffectResult(bet:number,effect:VikingDestructionResult,refill:(column:number,row:number)=>number):SpinResult{
 const following=vikingOrdinaryCascade(effect.after,bet,refill,{effectPlayed:true});
 const result=vikingOrdinaryResult(bet,following),stage=vikingDestructionStage(effect);
 return {...result,openingBoard:[...stage.board],cascades:[stage,...result.cascades!]};
}
