import {isLocalMode} from './LocalMode';
import {LocalFreeSpinLease} from './LocalFreeSpinSession';
import {postGameRequest} from './QuestClient';
import {WeeklyFreeSpinPlan,WeeklyFreeSpinState,WeeklyFreeSpinToday,validateWeeklyFreeSpinPlan,WEEKLY_FREE_SPIN_COUNT} from './WeeklyFreeSpins';
export type FreeSpinAction='status'|'start'|'forfeit'|'settle'|'choose'|'start-local'|'finish-local';
export interface FreeSpinReply {plan:WeeklyFreeSpinPlan;state:WeeklyFreeSpinState;today:WeeklyFreeSpinToday|null;save:unknown;revision:number;creditedCoins:number;rewardCoins:number;roundId?:string;completed:boolean;serverNow:number;localSession?:LocalFreeSpinLease;}
export async function weeklyFreeSpinsRequest(token:string,action:FreeSpinAction,expectedRevision:number,requestId:string,details:{slot?:string;bet?:number;played?:number;payouts?:number[];selected?:number;roundId?:string;sessionId?:string;payout?:number;outcome?:'completed'|'forfeited'}={}):Promise<FreeSpinReply>{
 if(isLocalMode())throw Object.assign(Error('FREE_SPINS_ONLINE_ONLY'),{code:'FREE_SPINS_ONLINE_ONLY'});
 const response=await postGameRequest(token,'https://asia-northeast3-in-my-pocket-slots.cloudfunctions.net/weeklyFreeSpins',JSON.stringify({action,expectedRevision,requestId,...details}));
 let body:any;try{body=JSON.parse(response.text);}catch{body={};}
 if(response.status<200||response.status>=300)throw Object.assign(Error(body.error||'FREE_SPINS_UNAVAILABLE'),{code:body.error||'FREE_SPINS_UNAVAILABLE',httpStatus:response.status});
 const plan=validateWeeklyFreeSpinPlan(body.plan),state=body.state;
 if(!state||state.weekKey!==plan.weekKey||!Array.isArray(state.days)||state.days.length!==6||state.days.some((day:any)=>!['idle','active','completed','forfeited'].includes(day.status)||!Number.isInteger(day.played)||day.played<0||day.played>WEEKLY_FREE_SPIN_COUNT)||typeof state.rewardGranted!=='boolean'||!body.save||!Number.isSafeInteger(body.revision)||!Number.isSafeInteger(body.creditedCoins)||!Number.isSafeInteger(body.rewardCoins)||!Number.isSafeInteger(body.serverNow))throw Error('FREE_SPINS_UNAVAILABLE');
 if(action==='start-local'){
  const lease=body.localSession;
  if(!lease||!/^[A-Za-z0-9_-]{8,120}$/.test(lease.id)||lease.weekKey!==plan.weekKey||lease.day!==body.today?.day||lease.slot!==body.today?.slotId||lease.basePlayed!==body.today?.played||lease.closed)throw Error('FREE_SPINS_UNAVAILABLE');
 }
 return {...body,plan};
}
