/** The multiplier belongs to the stopped wagon. It is not an invented free
 * spin accumulator. Prize values and selectable wagons are explicit fixtures. */
export function trainStopResult(triggerBoard:string[],triggerCells:number[],prize:number,wagons:number[],stopIndex:number,bet:number,startingMultiplier=1,triggerInput:Win[]=[]):SpinResult{
 boardOK(triggerBoard,triggerBoard.length);cellsOK(triggerCells,triggerBoard.length);
 if(!integer(bet,1)||!integer(prize,1)||!integer(startingMultiplier,1)||!wagons.length||wagons.some(value=>!integer(value,1))||!integer(stopIndex)||stopIndex>=wagons.length)throw Error('Invalid train stop');
 const multiplier=startingMultiplier+wagons[stopIndex],amount=prize*multiplier;if(!integer(amount))throw Error('Train payout overflow');
 const award:Win={line:-1,symbol:'slot-o-mania-train',cells:[...triggerCells],amount,multiplier};
 // A simultaneously supplied line award is settled before the stop feature;
 // the stopped wagon multiplies its prize only, never the line win.
 const triggerWins=copyWins(triggerInput,triggerBoard.length),wins=[...triggerWins,award],payout=wins.reduce((sum,win)=>sum+win.amount,0);
 if(!integer(payout))throw Error('Train payout overflow');
 return {bet,board:[...triggerBoard],payout,wins,trainFeature:{kind:'train-stop',triggerBoard:[...triggerBoard],triggerCells:[...triggerCells],prize,wagons:[...wagons],stopIndex,multiplier,startingMultiplier,award,triggerWins}};
}
