import {applyQuestRound,questSnapshot,QUEST_DAY_MS} from './QuestPolicy';
import type {QuestState,QuestTotals,QuestRound,QuestSlot,QuestSnapshot} from './QuestPolicy';
export type LocalMissionState=QuestState&{localRoundIds?:Record<string,number>};
const copy=<T>(value:T):T=>JSON.parse(JSON.stringify(value));
const union=<T>(a:T[],b:T[])=>Array.from(new Set([...a,...b]));
function mergeTotals(local:QuestTotals,server:QuestTotals):QuestTotals{
 const result=copy(server);
 for(const key of Object.keys(local.all) as (keyof QuestTotals['all'])[])result.all[key]=Math.max(local.all[key]||0,result.all[key]||0);
 for(const [slot,values]of Object.entries(local.slots)){
  const target=result.slots[slot]||(result.slots[slot]=copy(values));
  for(const key of Object.keys(values) as (keyof typeof values)[])target[key]=Math.max(values[key]||0,target[key]||0);
 }
 return result;
}
/** Keep durable counters while taking earned/paid reward rights from the server. */
export function mergeMissionState(local:LocalMissionState|null,server:QuestState):LocalMissionState{
 const merged:LocalMissionState=copy(server);if(!local)return merged;
 merged.localRoundIds={...local.localRoundIds};merged.lifetime=mergeTotals(local.lifetime,server.lifetime);
 for(const [id,day]of Object.entries(local.days)){
  const remote=merged.days[id];
  if(!remote){merged.days[id]=copy(day);continue;}
  remote.totals=mergeTotals(day.totals,remote.totals);
  // A server catalog change owns the day's task definitions.
  const valid=new Set(remote.quests.map(q=>q.id));
  remote.completed=union(remote.completed,day.completed.filter(q=>valid.has(q)));
  remote.milestones=union(remote.milestones,day.milestones);remote.allComplete=remote.allComplete||day.allComplete;
 }
 merged.dailyCompleted=Math.max(local.dailyCompleted,server.dailyCompleted);merged.allDays=Math.max(local.allDays,server.allDays);
 return merged;
}
/** Deduplicate replay from the pending ranking queue and retain seven days only. */
export function recordLocalMissionRound(state:LocalMissionState,round:QuestRound,catalog:QuestSlot[],now:number){
 if(state.localRoundIds?.[round.id]!==undefined)return false;
 if(!applyQuestRound(state,round,catalog,now))return false;
 state.localRoundIds=Object.fromEntries(Object.entries({...state.localRoundIds,[round.id]:round.recordedAt}).filter(([,at])=>at>=now-7*QUEST_DAY_MS));
 return true;
}
/** Local progress may finish early; only server-confirmed rights are claimable online. */
export function missionSnapshot(state:LocalMissionState,catalog:QuestSlot[],now:number,server?:QuestSnapshot):QuestSnapshot{
 const local=questSnapshot(copy(state),catalog,now);if(!server)return local;
 const daily=new Map(server.daily.map(row=>[row.id,row])),lifetime=new Map(server.lifetime.map(row=>[row.id,row]));
 return {...local,pendingCoins:server.pendingCoins,earnedCoins:server.earnedCoins,paidCoins:server.paidCoins,
  daily:local.daily.map(row=>({...row,progress:row.complete?row.target:row.progress,rewardState:server.dayId===local.dayId?daily.get(row.id)?.rewardState||'active':'active'})),
  lifetime:local.lifetime.map(row=>({...row,rewardState:lifetime.get(row.id)?.rewardState||'active',earnedTiers:lifetime.get(row.id)?.earnedTiers,claimedTiers:lifetime.get(row.id)?.claimedTiers})),
  milestones:local.milestones.map(row=>({...row,rewardState:server.dayId===local.dayId?server.milestones.find(m=>m.target===row.target)?.rewardState||'active':'active'})),
  allCompleteState:server.dayId===local.dayId?server.allCompleteState:'active'};
}
