import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
export const KEEP_ID='full-moon-keep';
export const keepSymbol=(n:number)=>KEEP_ID+'-'+(n===10?'wild':n===11?'scatter':n===12?'coin':n);
export interface KeepMoon {cell:number;tier:string;win:Win;}
export interface KeepPlayback {lineWins:Win[];moons:KeepMoon[];coinAward?:Win;coinCount:number;}
export const KEEP_PAYS=[[.6,1.7,5.6],[.4,1,3.6],[.3,.8,2.8],[.2,.7,2.4],[.2,.6,2],[.2,.5,1.6],[.1,.2,.8],[.1,.2,.8],[.1,.2,.3],[.1,.2,.3]];
const TIERS=['MINI','MINOR','MAJOR','ULTRA','GRAND'];
export const keepFreeSpins=(n:number)=>n>=5?10:n===4?7:n===3?5:0;
/** Source mechanics: DoubleU Werewolf Windfall; public demo help is the RMG
 * variant. Reel weights, standard 25-line layout and once-per-moon collection
 * are explicit local adaptations, not a claim to reproduce unpublished math. */
export class FullMoonKeepSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;
 readonly bonusCalibrationKey=KEEP_ID+':moon-coins-v1';
 get bonusSymbol(){return keepSymbol(11);}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'달빛이 성문에 모입니다',triggerText:'보름달 성문 개방',bonusInText:'달 WILD · 늑대 코인',hitText:'성의 보물을 발견했습니다',totalWinText:'늑대성 총 보상',signature:'당첨선 달 WILD 포트 · 코인 개수 보상',uiEffect:'달 점등 후 포트 수집',soundCue:'featureLand',anticipationHold:.3,hitHold:.2,outHold:.5};
 readonly config:SlotConfig={id:KEEP_ID,title:'보름달 늑대성',subtitle:'FULL MOON KEEP',tag:'MOON POTS · WOLF COINS',color:'#26344e',accent:'#afcdee',description:'5×3 · 25라인\n3~5번 릴의 달 WILD는 당첨선에 포함될 때만 포트 지급\n코인 5/7/9/12/15개: 10/30/80/300/10000배\n성문 3/4/5개: 무료 5/7/10회 · 무료 중에도 재진입\n순수 문장 5개는 10000배 · WILD 대체는 일반 배당',symbols:[...['성 문장','은빛 늑대','도끼','방패','장갑','늑대 부적','A','K','Q','J','달 WILD','성문 SCATTER','늑대 코인'].map((name,n)=>({id:keepSymbol(n),name,color:'#accce6',weight:[3,4,5,6,7,8,12,12,13,13,6,1.8,7][n],payout:n<10?KEEP_PAYS[n][2]:0}))]};
 private board(rng:()=>number){const scatterColumns=new Set<number>();return Array.from({length:15},(_,cell)=>{let weights=this.config.symbols.map(s=>s.weight);if(cell%5<2)weights[10]=0;if(scatterColumns.has(cell%5))weights[11]=0;let n=rng()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<weights.length;i++){n-=weights[i];if(n<0){if(i===11)scatterColumns.add(cell%5);return keepSymbol(i);}}return keepSymbol(9);});}
 private validate(board:string[],bet:number){if(!this.bets.includes(bet)||board.length!==15||board.some((id,c)=>!this.config.symbols.some(s=>s.id===id)||(id===keepSymbol(10)&&c%5<2)))throw Error('Invalid keep spin');}
 evaluate(board:string[],bet:number,rng:()=>number=()=>.5):SpinResult{
  this.validate(board,bet);const lineWins:Win[]=[];
  WOLF_LINES.forEach((line,index)=>{const n=this.config.symbols.findIndex(s=>s.id===board[line[0]]);if(n<0||n>=10)return;const cells:number[]=[];for(const cell of line){if(board[cell]!==keepSymbol(n)&&board[cell]!==keepSymbol(10))break;cells.push(cell);}if(cells.length<3)return;const multiple=n===0&&cells.length===5&&cells.every(c=>board[c]===keepSymbol(0))?10000:KEEP_PAYS[n][cells.length-3];lineWins.push({line:index,symbol:keepSymbol(n),cells,amount:Math.round(bet*multiple),multiplier:multiple});});
  const winningCells=new Set(lineWins.flatMap(w=>w.cells));const moons:KeepMoon[]=[];
  for(const cell of winningCells)if(board[cell]===keepSymbol(10)){const roll=rng();if(roll<.4){const tier=roll<.006?4:roll<.02?3:roll<.055?2:roll<.14?1:0,multiple=[10,20,30,50,100][tier];moons.push({cell,tier:TIERS[tier],win:{line:-2,symbol:keepSymbol(10),cells:[cell],amount:bet*multiple,multiplier:multiple}});}}
  const coins=board.flatMap((id,c)=>id===keepSymbol(12)?[c]:[]),count=coins.length,multiple=count>=15?10000:count>=12?300:count>=9?80:count>=7?30:count>=5?10:0;
  const coinAward=multiple?{line:-3,symbol:keepSymbol(12),cells:coins,amount:bet*multiple,multiplier:multiple}:undefined;
  const wins=[...lineWins,...moons.map(m=>m.win),...(coinAward?[coinAward]:[])];let left=bet*this.maxWin;for(const w of wins){w.amount=Math.min(left,w.amount);left-=w.amount;}
  return{bet,board:[...board],wins,payout:bet*this.maxWin-left,keepFeature:{lineWins,moons,coinAward,coinCount:count},presentation:this.presentation};
 }
 private sequence(base:SpinResult,rng:()=>number){const result=this.freeSpinSequence(base,()=>this.evaluate(this.board(rng),base.bet,rng),r=>keepFreeSpins(r.board.filter(s=>s===this.bonusSymbol).length));result.presentation=this.presentation;result.featureName='보름달 성문 무료 회전';if(result.rounds)result.bonusEndReason=result.payout>=base.bet*this.maxWin?'max-win':'spins-exhausted';return result;}
 spin(bet:number,rng:()=>number=Math.random){return this.sequence(this.evaluate(this.board(rng),bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=this.board(rng);for(const cell of [0,6,12])board[cell]=this.bonusSymbol;for(let c=0;c<15;c++)if(![0,6,12].includes(c)&&board[c]===this.bonusSymbol)board[c]=keepSymbol(9);const base:SpinResult={bet,board,wins:[],payout:0,presentation:this.presentation};const result=this.sequence(base,rng);result.bonusTriggerRound=base;result.rounds=result.rounds!.slice(1);result.wins=result.rounds.flatMap(r=>r.wins);result.payout=result.wins.reduce((s,w)=>s+w.amount,0);return result;}
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>keepSymbol((i+Math.floor(i/5))%10));board[5]=board[6]=keepSymbol(1);board[7]=keepSymbol(10);for(const c of [0,3,4,10,14])board[c]=keepSymbol(12);return this.evaluate(board,bet,()=>.1);}
 bonusDemoSpin(bet:number){let seed=912;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};return this.prepareBonusPurchase(bet,rng);}
}
