 private node(name:string,parent:Node,width:number,height:number,x:number,y:number){const node=new Node(name);node.layer=parent.layer;parent.addChild(node);const t=node.addComponent(UITransform);t.setContentSize(width,height);node.setPosition(x,y);return node;}
