  label.fontSize=size;label.lineHeight=size*1.2;label.color=new Color(color);label.horizontalAlign=Label.HorizontalAlign.CENTER;label.verticalAlign=Label.VerticalAlign.CENTER;label.overflow=Label.Overflow.SHRINK;label.enableWrapText=false;node.getComponent(UITransform)!.setContentSize(width,size*1.6);return label;
