import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,SlotPresentation,Win} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
import {validateSocialBoard,socialSeed} from './Social1921Rules';

export const CIRCUS_ID='second-chance-circus';
export const CIRCUS_PAYS=[[1.5,4,10],[1.25,3,7.5],[1,2.5,6],[.75,2,5],[.5,1.5,4],[.5,1.25,3],[.5,1,2.5],[.5,1,2]].map(row=>row.map(n=>n*.9576));
export interface CircusPlayback {stage:'base'|'rescue';locked:number[];trigger:boolean;}
/** Betty's Circus supplies the losing-board + two wilds trigger. The 25-line
 * table and exactly one rescue (including newly landed wilds) are local rules. */
export class SecondChanceCircusSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];
 readonly maxWin=1000;
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'안전망을 기다립니다',triggerText:'안전망 고정',bonusInText:'한 번 더 · 무료 재회전',hitText:'서커스 라인 당첨',totalWinText:'서커스 총 보상',signature:'무당첨과 WILD 2개 이상일 때만 1회 고정 재시도',uiEffect:'안전망 고정 → 나머지 칸 재회전 → 해제',soundCue:'featureLand',anticipationHold:.3,hitHold:.25,outHold:.4};
 readonly config:SlotConfig={id:CIRCUS_ID,title:'실패 구제 서커스',subtitle:'SECOND CHANCE CIRCUS',tag:'ONE RESCUE',color:'#422e45',accent:'#efaa72',description:'5×3 · 25라인 · 왼쪽부터 3개 이상\nWILD는 모든 일반 심볼을 대신합니다.\n무당첨이고 안전망 WILD가 2개 이상이면 고정 후 무료 재회전 1회.\n새 WILD가 나와도 추가 재회전은 없습니다.\n재회전 뒤 모든 고정이 해제됩니다. ',symbols:['천막','실크햇','저글링 곤봉','외바퀴자전거','트럼펫','공중그네','공연 북','깃발','안전망 WILD'].map((name,n)=>({id:CIRCUS_ID+'-'+(n===8?'wild':n),name,color:'#efaa72',weight:[5,6,7,8,10,12,14,16,4][n],payout:n<8?CIRCUS_PAYS[n][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult{
  validateSocialBoard(this.config,board,bet,this.bets,15);const wins:Win[]=[];
  WOLF_LINES.forEach((line,index)=>{let best:Win|undefined;for(let n=0;n<8;n++){const cells:number[]=[];for(const c of line){if(board[c]!==CIRCUS_ID+'-'+n&&board[c]!==CIRCUS_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const multiplier=CIRCUS_PAYS[n][cells.length-3],amount=Math.round(bet*multiplier);if(!best||amount>best.amount)best={line:index,symbol:CIRCUS_ID+'-'+n,amount,cells,multiplier};}if(best)wins.push(best);});
  return{board:[...board],bet,wins,payout:wins.reduce((s,w)=>s+w.amount,0),presentation:this.presentation};
 }
 resolve(board:string[],bet:number,rng:()=>number):SpinResult{
  const base=this.evaluate(board,bet),locked=board.flatMap((id,c)=>id===CIRCUS_ID+'-wild'?[c]:[]),trigger=base.payout===0&&locked.length>=2;
  base.circusFeature={stage:'base',locked:trigger?[...locked]:[],trigger};if(!trigger)return base;
  const next=board.map((id,c)=>locked.includes(c)?id:this.pick(rng)),rescue=this.evaluate(next,bet);
  rescue.heldAtStart=locked.map(cell=>({cell,symbol:CIRCUS_ID+'-wild',value:0}));
  rescue.circusFeature={stage:'rescue',locked:[...locked],trigger:false};rescue.freeSpinsRemaining=0;rescue.roundLabel='안전망 고정 · 마지막 무료 재회전';
  return{board:[...next],bet,payout:rescue.payout,wins:rescue.wins,rounds:[base,rescue],freeSpinsAwarded:1,featureName:'안전망 재회전',presentation:this.presentation};
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.resolve(Array.from({length:15},()=>this.pick(rng)),bet,rng);}
 demoSpin(bet:number){const rng=socialSeed(2201);for(let n=0;n<10000;n++){const result=this.spin(bet,rng);if(result.rounds&&result.payout>0)return result;}throw Error('Circus preview unavailable');}
 bonusDemoSpin(bet:number){return this.demoSpin(bet);}
}
