import type {LocalStorage} from './AccountStorage';
export const LOCAL_MODE_KEY='pocket-local-test-mode';
export const LOCAL_SAVE_PREFIX='pocket-offline-test:';
let testBuild=false,active=false;
/** Read once on boot; mode changes apply only after a full app restart. */
export function configureLocalMode(isTestBuild:boolean,storage:LocalStorage){testBuild=isTestBuild;active=testBuild&&storage.getItem(LOCAL_MODE_KEY)!=='off';}
export function isLocalTestBuild(){return testBuild;}
export function isLocalMode(){return active;}
export function nextLocalMode(storage:LocalStorage){return storage.getItem(LOCAL_MODE_KEY)!=='off';}
export function setNextLocalMode(storage:LocalStorage,enabled:boolean){if(!testBuild)return;storage.setItem(LOCAL_MODE_KEY,enabled?'on':'off');}
/** Never migrate, import or upload an online account's save. */
export function localTestStorage(storage:LocalStorage):LocalStorage{return {getItem:key=>storage.getItem(LOCAL_SAVE_PREFIX+key),setItem:(key,value)=>storage.setItem(LOCAL_SAVE_PREFIX+key,value)};}
