import {VikingDirectGift} from './VikingFeatures';
import {vikingClusters} from './VikingWildRules';
import {vikingOrdinaryCascade} from './VikingCascade';
import {vikingOrdinaryResult,vikingSymbol} from './VikingResult';
import type {SpinResult} from './SlotMain';
export interface VikingGiftPlayback {god:VikingDirectGift|'freya';waves?:number[][];before:string[];after:string[];cells:number[];symbol:string;}
/** Direct god gifts on non-winning boards. Selection odds belong to the full
 * engine; callers provide the selected cells (no forced winning board here).
 * Freya's repeated growth needs its own confirmed geometry and wave events.
 */
export function vikingGiftResult(initial:readonly number[],bet:number,god:VikingDirectGift,cells:readonly number[],refill:(column:number,row:number)=>number):SpinResult {
 if(vikingClusters(initial,bet).length)throw Error('God gift requires a non-winning board');
 if(new Set(cells).size!==cells.length||cells.some(c=>!Number.isInteger(c)||c<0||c>=49))throw Error('Invalid Viking gift cells');
 if(god==='thor'&&(cells.length<5||cells.length>9))throw Error('Thor requires five to nine cells');
 if(god==='heimdall'&&(cells.length!==7||new Set(cells.map(c=>Math.floor(c/7))).size!==7))throw Error('Heimdall requires one cell in each row');
 if(god==='odin'){
  const rest=[...cells].sort((a,b)=>a-b);
  if(rest.length!==4)throw Error('Odin requires two vertical pairs');
  while(rest.length){const first=rest.shift()!,index=rest.indexOf(first+7);if(index<0)throw Error('Odin requires two vertical pairs');rest.splice(index,1);}
 }
 const wild=god==='thor'?9:god==='odin'?10:god==='heimdall'?12:NaN;
 if(!Number.isFinite(wild))throw Error('Unsupported Viking gift');
 const after=[...initial];cells.forEach(cell=>after[cell]=wild);
 const segment=vikingOrdinaryCascade(after,bet,refill),result=vikingOrdinaryResult(bet,segment);
 return {...result,vikingGod:god,openingBoard:initial.map(vikingSymbol),vikingGift:{god,before:initial.map(vikingSymbol),after:after.map(vikingSymbol),cells:[...cells],symbol:vikingSymbol(wild)}};
}

/** Freya's confirmed contract: four new WILDs per wave, first wave inside
 * the inner 5x5, stopping at the FIRST paying board. Locations are supplied
 * explicitly until the original cluster growth geometry is observed.
 * Reject ambiguous WILD awards; this is not a natural feature planner. */
export function vikingFreyaGiftResult(initial:readonly number[],bet:number,waves:readonly (readonly number[])[],refill:(column:number,row:number)=>number):SpinResult {
 if(vikingClusters(initial,bet).length)throw Error('God gift requires a non-winning board');
 if(!waves.length)throw Error('Freya requires growth waves');
 const after=[...initial],cells:number[]=[];let won=false;
 for(const [index,wave] of waves.entries()){
  if(won)throw Error('Freya must stop at the first winning wave');
  if(wave.length!==4||new Set(wave).size!==4||wave.some(c=>!Number.isInteger(c)||c<0||c>=49||after[c]>=9))throw Error('Freya requires four new WILD cells per wave');
  if(index===0&&wave.some(c=>c%7<1||c%7>5||Math.floor(c/7)<1||Math.floor(c/7)>5))throw Error('Freya seeds must be inside the inner 5x5');
  wave.forEach(c=>{after[c]=11;cells.push(c);});
  won=vikingClusters(after,bet).length>0;
 }
 if(!won)throw Error('Freya growth must reach a winning board');
 const result=vikingOrdinaryResult(bet,vikingOrdinaryCascade(after,bet,refill));
 return {...result,vikingGod:'freya',openingBoard:initial.map(vikingSymbol),vikingGift:{god:'freya',before:initial.map(vikingSymbol),after:after.map(vikingSymbol),cells,symbol:vikingSymbol(11),waves:waves.map(w=>[...w])}};
}
