import {ExpansionSlot,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult} from './SlotMain';
/** Growing reels and mirroring WILDs. The original trivia is reinterpreted as a solvable symbol quiz. */
export const MIRROR_LADDER=[0,1,2,4,8,16,32,64,128];
export const mirrorWrongTier=(level:number)=>Math.max(0,Math.floor((level-1)/2)*2);
export class MirrorManorSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);for(const name of ['coin','rise','portrait','book'])this.config.symbols.push({id:this.id(name),name,color:'#c4a2ed',weight:0,payout:0});this.config.description='5×4 · 1,024 WAYS · 왼쪽부터 연결\n가운데 세 릴의 거울 WILD가 위나 아래로 확장합니다. 사과 8개: 무료 12회.\n무료 3회마다 한 행을 추가해 최대 7행. 사과 8개 재발동은 +3회·추가 회차는 7행, 전체 최대 120회입니다.\n일반 거울 WILD는 무작위로 문양 퀴즈를 엽니다. 8문제 정답은 최고 상금, 중도 수령 가능. 오답은 이전 안전 단계 상금입니다.\n문양 퀴즈·상금·확률은 로컬 각색입니다. 구매는 일반 퀴즈와 별개인 독립 무료 12회입니다.';}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-mirror';}
 draw(bet:number,rng:()=>number,g:Geometry={columns:5,rows:4}){if(!this.bets.includes(bet))throw Error('Invalid bet');return Array.from({length:g.columns*g.rows},(_,c)=>{const roll=rng();return this.id(roll<.12?'scatter':c%5>0&&c%5<4&&roll<.145?'wild':randomIndex(rng,8));});}
 private mirrored(b:string[],bet:number,rng:()=>number,g:Geometry){const after=[...b],wilds=cells(b,this.id('wild')),changed:number[]=[];for(const c of wilds){const dir=rng()<.5?-1:1,len=randomIndex(rng,g.rows),row=Math.floor(c/5),col=c%5;for(let n=1;n<=len;n++){const r=row+n*dir;if(r<0||r>=g.rows)break;const to=r*5+col;if(after[to]!==this.id('scatter')&&after[to]!==this.id('wild')){after[to]=this.id('wild');changed.push(to);}}}const fs=[this.frame(b,'reels',g.rows+'행 · 거울 WILD 착지',[],{},g)];if(changed.length)fs.push(this.frame(b,'trigger','거울 WILD · 세로 반사',wilds,{},g),this.frame(after,'effect','위·아래 확장 완료',changed,{},g));fs.push(this.hit(after,bet,'거울 WAYS 당첨',g));const apples=cells(b,this.id('scatter'));if(apples.length>=8)fs.push(this.prize(after,bet,7,apples,'사과 8개 이상 · 별도 SCATTER 상금',g));return this.round(bet,fs);}
 private freeGames(base:SpinResult,bet:number,rng:()=>number){const rounds=[base];let left=12,awarded=12,rows=4;for(let played=0;left>0&&played<120;played++){left--;const target=Math.max(rows,Math.min(7,4+Math.floor(played/3))),g={columns:5,rows:target},b=this.draw(bet,rng,g),r=this.mirrored(b,bet,rng,g);if(target>rows)r.expansionFeature!.frames.unshift(this.frame(b,'expand','세 회전 완료 · 한 행 추가',[],{},g));rows=target;const gates=cells(b,this.id('scatter'));if(gates.length>=8&&awarded<120){const added=Math.min(3,120-awarded);awarded+=added;left+=added;r.freeSpinsAdded=added;r.expansionFeature!.frames.push(this.frame(r.board,'trigger','사과 8개 · 무료 +'+added+'회',gates,{},g));}r.freeSpinsRemaining=left;rounds.push(r);}return this.finish(rounds,{freeSpinsAwarded:12,featureOnly:false});}
 private quiz(base:SpinResult,bet:number,rng:()=>number){const questions=Array.from({length:8},()=>{const options=Array.from({length:8},(_,i)=>i);for(let i=7;i>0;i--){const j=randomIndex(rng,i+1);[options[i],options[j]]=[options[j],options[i]];}const choices=options.slice(0,4).map(n=>this.id(n)),correct=randomIndex(rng,4);return{symbol:choices[correct],options:choices,correct,help:randomIndex(rng,3)};});const branches=MIRROR_LADDER.map((award,level)=>{const opening=this.round(bet,JSON.parse(JSON.stringify(base.expansionFeature!.frames)));opening.expansionFeature!.frames.push(this.frame(opening.board,'trigger','거울의 문양 시험 · 8단계',cells(opening.board,this.id('wild')),{}, {columns:5,rows:4}));const prize=this.prize(opening.board,bet,award,[],'거울 시험 · '+level+'/8 단계 확정',{columns:5,rows:4});return this.finish([opening,this.round(bet,[prize])],{featureOnly:true});});return{...branches[8],featureChoices:{title:'거울 문양 시험',labels:MIRROR_LADDER.map((_,i)=>String(i)),results:branches,defaultIndex:8,sampleIndices:[8],mirrorQuiz:{questions}}};}
 play(b:string[],bet:number,rng:()=>number){this.validate(b,bet,{columns:5,rows:4});const base=this.mirrored(b,bet,rng,{columns:5,rows:4}),gates=cells(b,this.id('scatter'));if(gates.length>=8){base.expansionFeature!.frames.push(this.frame(b,'trigger','사과 8개 · 무료 12회',gates,{}, {columns:5,rows:4}));return this.freeGames(base,bet,rng);}if(cells(b,this.id('wild')).length&&rng()<.015)return this.quiz(base,bet,rng);return this.finish([base]);}
 prepareBonusPurchase(bet:number,rng:()=>number){for(let i=0;i<50000;i++){const b=this.draw(bet,rng),gates=cells(b,this.id('scatter'));if(gates.length>=8)return this.purchaseFromResult(this.freeGames(this.round(bet,[this.frame(b,'trigger','독립 성장 무료 12회',gates,{}, {columns:5,rows:4})]),bet,rng));}throw Error('Mirror free gate unavailable');}
}
